_RETRYABLE_YFINANCE_: tuple[type[Exception], ...] = (ConnectionError, TimeoutError, OSError, YFRateLimitError)

def _is_rate_limit_error(exc: BaseException) -> bool:
    return isinstance(exc, YFRateLimitError)

def _create_retryable_er(action: str, exc: BaseException, details: dict[str, Any]) -> str:
    if _is_rate_limit_error(exc):
        message = f'Rate limit reached while {action}. Try again later.'
    else:
        message = f'Temporary network issue while {action}. Try again later.'
    return create_error_respons(message, error_code='NETWORK_ERROR', details={**details, 'exception': str(exc)})

@mcp.tool(name='yfinance_get_analyst_price_targets', annotations=ToolAnnotations(readOnlyHint=True, destructiveHint=False, idempotentHint=True, openWorldHint=True))
async def get_analyst_price_ta(symbol: Annotated[str, Field(description="Stock ticker symbol (e.g., 'AAPL', 'GOOGL', 'MSFT')")]) -> str:
    try:
        ticker = await asyncio.to_thread(yf.Ticker, symbol)
        targets = await asyncio.to_thread(lambda: ticker.analyst_price_target)
    except _RETRYABLE_YFINANCE_ as exc:
        return _create_retryable_er(f"fetching analyst price targets for '{symbol}'", exc, {'symbol': symbol})
    except Exception as exc:
        return create_error_respons(f"Failed to fetch analyst price targets for '{symbol}'. Verify the symbol is correct.", error_code='API_ERROR', details={'symbol': symbol, 'exception': str(exc)})
    if not targets:
        return create_error_respons(f"No analyst price targets available for '{symbol}'.", error_code='NO_DATA', details={'symbol': symbol})
    cleaned_targets: dict[str, Any] = {}
    for key, value in targets.items():
        if value is None:
            cleaned_targets[key] = None
            continue
        try:
            numeric = float(value)
        except (TypeError, ValueError):
            cleaned_targets[key] = value
            continue
        cleaned_targets[key] = None if numeric != numeric else numeric
    return dump_json(cleaned_targets)

